WITH exploded AS (SELECT id, host, log_ts, level, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v), kept_keys AS (SELECT level FROM exploded INTERSECT SELECT level FROM app_logs WHERE level IN ('WARN', 'DEBUG', 'INFO')), kept_rows AS (SELECT s.* FROM exploded s INNER JOIN kept_keys k ON s.level = k.level), cleaned AS (SELECT id, host, log_ts, level, v, CONCAT(key, ', ', host) AS key_host, CASE WHEN level IN ('DEBUG', 'ERROR') THEN 'Priority' ELSE 'Other' END AS level_group FROM kept_rows WHERE log_ts >= DATE '2025-06-02' AND key IS NOT NULL AND key != 'region'), filtered AS (SELECT *, LENGTH(host) AS host_length FROM cleaned WHERE level = 'INFO') SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, DATE_TRUNC('DAY', log_ts) AS activity_day, ROUND(AVG(host_length), 2) AS avg_host_length, SUM(host_length) AS total_host_length FROM filtered GROUP BY DATE_TRUNC('HOUR', log_ts), DATE_TRUNC('DAY', log_ts) ORDER BY total_host_length;
